import fs from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { digest } from '../handover/wire.js';
import { verifyImage } from '../handover/image.js';
import { assertImageRuntime } from './image-policy.js';

// Published code is shared by the two N-API profiles. Only manifest.json differs
// when an independent managed image is prepared; it is already the image
// format's sole self-digest exclusion. No code/dependency exclusion is added.
export function readPublishedPayload(directory) {
  const root = fs.realpathSync(directory), path = join(root, 'manifest.json'), info = fs.lstatSync(path);
  if (!info.isFile() || info.nlink !== 1 || (info.mode & 0o022)) throw Error('published_manifest_unqualified');
  const fd = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  let published;
  try {
    const opened = fs.fstatSync(fd);
    if (!opened.isFile() || opened.nlink !== 1 || (opened.mode & 0o022) || opened.dev !== info.dev || opened.ino !== info.ino) throw Error('published_manifest_changed');
    const bytes = fs.readFileSync(fd, 'utf8'), after = fs.fstatSync(fd), current = fs.lstatSync(path);
    if (after.size !== opened.size || after.mtimeMs !== opened.mtimeMs || after.ctimeMs !== opened.ctimeMs ||
      current.dev !== opened.dev || current.ino !== opened.ino) throw Error('published_manifest_changed');
    published = JSON.parse(bytes);
  } finally { fs.closeSync(fd); }
  if (!published || typeof published !== 'object' || Array.isArray(published) ||
    Object.keys(published).sort().join(',') !== 'kind,manifests,schemaVersion' || published.schemaVersion !== 1 ||
    published.kind !== 'h2a-published-payload' || !published.manifests || typeof published.manifests !== 'object' || Array.isArray(published.manifests)) {
    throw Error('published_manifest_invalid');
  }
  const names = Object.keys(published.manifests);
  if (!names.length || names.some(key => !['22', '24'].includes(key))) throw Error('published_profile_unknown');
  const manifest = published.manifests[process.versions.node.split('.')[0]];
  if (!manifest) throw Error('published_profile_absent');
  assertImageRuntime(manifest);
  let codeDigest;
  for (const key of names) {
    const candidate = published.manifests[key];
    if (candidate.profile?.nodeMajor !== Number(key)) throw Error('published_profile_mismatch');
    verifyImage(root, candidate, digest(candidate));
    const current = digest({ files: candidate.files, packageVersion: candidate.packageVersion,
      buildId: candidate.buildId, entrypoints: candidate.entrypoints });
    if (codeDigest && current !== codeDigest) throw Error('published_payload_profiles_disagree');
    codeDigest = current;
  }
  const pkg = JSON.parse(fs.readFileSync(join(root, 'package.json'), 'utf8'));
  if (pkg.version !== manifest.packageVersion) throw Error('published_package_version_mismatch');
  return { root, packageName: pkg.name, manifest, manifestDigest: digest(manifest), publishedDigest: digest(published) };
}
async function syncPaths(paths, directory) {
  const window = 16;
  for (let offset = 0; offset < paths.length; offset += window) {
    const batch = paths.slice(offset, offset + window).map(path => new Promise((resolve, reject) => {
      let fd;
      try {
        fd = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | (directory ? fs.constants.O_DIRECTORY : 0));
        fs.fsync(fd, error => {
          try { fs.closeSync(fd); } catch (cause) { error ??= cause; }
          if (error) reject(error); else resolve();
        });
      } catch (cause) {
        if (fd !== undefined) try { fs.closeSync(fd); } catch {}
        reject(cause);
      }
    }));
    // A failure must not race destination cleanup with still-open sibling fds.
    const results = await Promise.allSettled(batch);
    const failure = results.find(result => result.status === 'rejected');
    if (failure) throw failure.reason;
  }
}
async function syncTree(root) {
  const files = [], levels = [];
  function walk(directory, depth) {
    (levels[depth] ??= []).push(directory);
    for (const name of fs.readdirSync(directory)) {
      const path = join(directory, name), info = fs.lstatSync(path);
      if (info.isDirectory()) walk(path, depth + 1);
      else if (info.isFile()) files.push(path);
    }
  }
  walk(root, 0);
  await syncPaths(files, false);
  for (let depth = levels.length - 1; depth >= 0; depth--) await syncPaths(levels[depth], true);
}
// Preparation is independent of H4 authority. It neither selects nor changes a
// mutable npm tree. The caller still needs maintained exclusion before selection.
export async function preparePublishedImage(source, destination) {
  const published = readPublishedPayload(source);
  destination = resolve(destination);
  if (fs.realpathSync(dirname(destination)) !== dirname(destination)) throw Error('image_destination_noncanonical');
  fs.mkdirSync(destination, { mode: 0o700 });
  try {
    fs.cpSync(published.root, destination, { recursive: true, dereference: false, verbatimSymlinks: true, errorOnExist: true, force: false });
    fs.chmodSync(destination, 0o700);
    verifyImage(destination, published.manifest, published.manifestDigest);
    fs.writeFileSync(join(destination, 'manifest.json'), JSON.stringify(published.manifest, null, 2) + '\n');
    await syncTree(destination);
    const parentFd = fs.openSync(dirname(destination), fs.constants.O_RDONLY | fs.constants.O_DIRECTORY | fs.constants.O_NOFOLLOW);
    try { fs.fsyncSync(parentFd); } finally { fs.closeSync(parentFd); }
    verifyImage(destination, published.manifest, published.manifestDigest);
    return { ...published, root: destination };
  } catch (cause) { fs.rmSync(destination, { recursive: true, force: true }); throw cause; }
}

import { test as nodeTest } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { createManifest, verifyImage } from '../src/runtime/handover/image.js';
import { digest } from '../src/runtime/handover/wire.js';
import { readPublishedPayload, preparePublishedImage } from '../src/runtime/upgrade/published-payload.js';
const test = (name, body) => { if (!process.env.MH_L6_CASE || process.env.MH_L6_CASE === name) nodeTest(name, body); };
function fixture(t) {
  const directory = fs.mkdtempSync(join(tmpdir(), 'mh-l6-published-')), root = join(directory, 'package');
  fs.mkdirSync(root, { mode: 0o755 }); t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
  fs.writeFileSync(join(root, 'package.json'), '{"name":"@fixture/sdk","version":"0.98.7","type":"module"}');
  fs.writeFileSync(join(root, 'entry.mjs'), 'export default 42;');
  const base = createManifest(root, { packageVersion: '0.98.7', buildId: 'future-published-build',
    profile: { platform: 'linux', arch: process.arch, libc: 'glibc', nodeMajor: 22, nodeAbi: '127' },
    entrypoints: { main: 'entry.mjs' }, startupWaitBudgetMs: 10000, maxAttachments: 64, nativeArtifacts: [] });
  const matrix = { schemaVersion: 1, kind: 'h2a-published-payload', manifests: {
    '22': base, '24': { ...base, profile: { ...base.profile, nodeMajor: 24, nodeAbi: '137' } }
  } };
  const path = join(root, 'manifest.json'), write = value => fs.writeFileSync(path, JSON.stringify(value, null, 2) + '\n'); write(matrix);
  return { directory, root, path, matrix, write, destination: join(directory, 'image') };
}
test('U10 should choose the current Node profile from one immutable published payload', async t => {
  const f = fixture(t), bytes = fs.readFileSync(f.path), observed = readPublishedPayload(f.root);
  assert.equal(observed.manifest.profile.nodeMajor, Number(process.versions.node.split('.')[0]));
  assert.equal(observed.manifest.profile.nodeAbi, process.versions.modules);
  assert.equal(observed.manifestDigest, digest(f.matrix.manifests[process.versions.node.split('.')[0]]));
  assert.deepEqual(fs.readFileSync(f.path), bytes);
});
test('U10 should prepare a private durable image by changing only excluded manifest metadata', async t => {
  const f = fixture(t), before = fs.readFileSync(f.path), source = readPublishedPayload(f.root);
  const image = await preparePublishedImage(f.root, f.destination), stored = JSON.parse(fs.readFileSync(join(f.destination, 'manifest.json')));
  assert.deepEqual(stored, source.manifest); assert.equal(image.manifestDigest, source.manifestDigest);
  assert.equal(fs.statSync(f.destination).mode & 0o777, 0o700);
  assert.equal(verifyImage(f.destination, image.manifest, image.manifestDigest).verified, true);
  for (const row of image.manifest.files) if (row.type === 'file') assert.deepEqual(fs.readFileSync(join(f.root, row.path)), fs.readFileSync(join(f.destination, row.path)));
  assert.deepEqual(fs.readFileSync(f.path), before);
  assert.equal(fs.existsSync(join(f.directory, 'h2a-managed')), false);
});
test('U10 should refuse an absent Node profile before any image is prepared', async t => {
  const f = fixture(t); delete f.matrix.manifests[process.versions.node.split('.')[0]]; f.write(f.matrix);
  await assert.rejects(() => preparePublishedImage(f.root, f.destination), /published_profile_absent/);
  assert.equal(fs.existsSync(f.destination), false);
});
test('U10 should refuse corrupt code claims in a nonselected published profile', async t => {
  const f = fixture(t), other = process.versions.node.startsWith('22.') ? '24' : '22';
  f.matrix.manifests[other] = structuredClone(f.matrix.manifests[other]);
  f.matrix.manifests[other].files.find(row => row.path === 'entry.mjs').digest = 'sha256:' + '0'.repeat(64); f.write(f.matrix);
  await assert.rejects(() => preparePublishedImage(f.root, f.destination), /payload_mismatch/);
  assert.equal(fs.existsSync(f.destination), false);
});
test('U10 should refuse contradictory build identities between profiles with identical code', async t => {
  const f = fixture(t); f.matrix.manifests['24'] = { ...f.matrix.manifests['24'], buildId: 'different-build' }; f.write(f.matrix);
  assert.throws(() => readPublishedPayload(f.root), /published_payload_profiles_disagree/);
});
test('U10 should refuse an unsupported or incorrectly bound profile and unknown envelope fields', async t => {
  const f = fixture(t), original = structuredClone(f.matrix);
  for (const bad of [null, { ...original, unknown: true }, { ...original, manifests: { '25': original.manifests['24'] } },
    { ...original, manifests: { '22': original.manifests['24'], '24': original.manifests['22'] } }]) {
    f.write(bad); assert.throws(() => readPublishedPayload(f.root), /published_manifest_invalid|published_profile_unknown|published_profile_mismatch|image_loader_unqualified/);
  }
});
test('U10 should bind published version metadata to the actual package version', async t => {
  const f = fixture(t);
  for (const manifest of Object.values(f.matrix.manifests)) manifest.packageVersion = '0.98.8'; f.write(f.matrix);
  assert.throws(() => readPublishedPayload(f.root), /published_package_version_mismatch/);
});
test('U10 should remove only its own new destination when source code changes during the copy', async t => {
  const f = fixture(t), original = fs.cpSync;
  fs.cpSync = function(source, ...args) { if (source === f.root) fs.appendFileSync(join(f.root, 'entry.mjs'), '\n// changed after verification'); return original.call(this, source, ...args); };
  try { await assert.rejects(() => preparePublishedImage(f.root, f.destination), /payload_mismatch/); }
  finally { fs.cpSync = original; }
  assert.equal(fs.existsSync(f.destination), false); assert.equal(fs.existsSync(f.path), true);
});
test('U10 should never overwrite or remove a preexisting image destination', async t => {
  const f = fixture(t); fs.mkdirSync(f.destination); fs.writeFileSync(join(f.destination, 'sentinel'), 'preserve');
  await assert.rejects(() => preparePublishedImage(f.root, f.destination), /EEXIST/);
  assert.equal(fs.readFileSync(join(f.destination, 'sentinel'), 'utf8'), 'preserve');
});
test('U10 should refuse image preparation when a durable payload sync fails', async t => {
  const f = fixture(t), original = fs.fsync, before = fs.readFileSync(f.path);
  fs.fsync = (fd, callback) => { if (fs.fstatSync(fd).isFile()) return queueMicrotask(() => callback(Error('injected_payload_sync'))); return original(fd, callback); };
  try { await assert.rejects(() => preparePublishedImage(f.root, f.destination), /injected_payload_sync/); }
  finally { fs.fsync = original; }
  assert.equal(fs.existsSync(f.destination), false); assert.deepEqual(fs.readFileSync(f.path), before);
});

test('U10 should preserve internal link bytes and execute the copied image after the mutable source disappears', async t => {
  const f = fixture(t); fs.symlinkSync('./entry.mjs', join(f.root, 'alias.mjs'));
  for (const key of Object.keys(f.matrix.manifests)) f.matrix.manifests[key] = createManifest(f.root, f.matrix.manifests[key]);
  f.write(f.matrix);
  const image = await preparePublishedImage(f.root, f.destination);
  assert.equal(fs.readlinkSync(join(f.destination, 'alias.mjs')), './entry.mjs');
  fs.rmSync(f.root, { recursive: true });
  assert.equal(verifyImage(f.destination, image.manifest, image.manifestDigest).verified, true);
  assert.equal((await import(pathToFileURL(join(f.destination, 'alias.mjs')))).default, 42);
});

test('U10 should durably publish the image directory entry before returning and refuse a failed parent sync', async t => {
  const f = fixture(t), parent = fs.statSync(f.directory), original = fs.fsyncSync;
  let observed = false, fail = false;
  fs.fsyncSync = fd => {
    const info = fs.fstatSync(fd);
    if (info.dev === parent.dev && info.ino === parent.ino) {
      observed = true;
      if (fail) throw Error('injected_image_parent_sync');
    }
    return original(fd);
  };
  try {
    await preparePublishedImage(f.root, f.destination);
    assert.equal(observed, true, 'syncing files and the image itself does not persist its entry in the parent directory');
    fail = true; const next = join(f.directory, 'second-image');
    await assert.rejects(() => preparePublishedImage(f.root, next), /injected_image_parent_sync/);
    assert.equal(fs.existsSync(next), false); assert.equal(fs.existsSync(f.destination), true);
  } finally { fs.fsyncSync = original; }
});

test('U10 should reject unsupported platform and architecture before creating an image directory', async t => {
  const f = fixture(t);
  for (const [field, value] of [['platform', 'darwin'], ['arch', 'arm64']]) {
    const original = Object.getOwnPropertyDescriptor(process, field);
    try { Object.defineProperty(process, field, { value, configurable: true });
      await assert.rejects(() => preparePublishedImage(f.root, f.destination), /image_loader_unqualified/);
      assert.equal(fs.existsSync(f.destination), false);
    } finally { Object.defineProperty(process, field, original); }
  }
});
test('U10 should reject a libc below the pinned native baseline before any image preparation', async t => {
  const f = fixture(t), original = process.report.getReport;
  try {
    process.report.getReport = () => ({ header: { glibcVersionRuntime: '2.30' } });
    await assert.rejects(() => preparePublishedImage(f.root, f.destination), /image_loader_unqualified/);
    assert.equal(fs.existsSync(f.destination), false);
  } finally { process.report.getReport = original; }
});

test('U10 should wait for bounded outstanding payload syncs before cleaning a failed image', async t => {
  const f = fixture(t), original = fs.fsync;
  for (let n = 0; n < 40; n++) fs.writeFileSync(join(f.root, `module-${n}.mjs`), `export default ${n};`);
  for (const key of Object.keys(f.matrix.manifests)) f.matrix.manifests[key] = createManifest(f.root, f.matrix.manifests[key]);
  f.write(f.matrix);
  let issued = 0, active = 0, maximum = 0, failed = false, held, closing = false, ready;
  const reached = new Promise(resolve => { ready = resolve; }), callbacks = [];
  const observe = () => { if (failed && held) ready(); };
  fs.fsync = (fd, callback) => {
    const sequence = ++issued; active++; maximum = Math.max(maximum, active);
    let completed; callbacks.push(new Promise(resolve => { completed = resolve; }));
    original(fd, error => {
      const finish = cause => { active--; completed(); callback(cause); };
      if (sequence === 1) { failed = true; finish(Error('injected_parallel_sync')); observe(); }
      else if (sequence === 2 && !closing) { held = () => { held = undefined; finish(error); }; observe(); }
      else finish(error);
    });
  };
  let operation, completion, settled = false, failure;
  try {
    operation = preparePublishedImage(f.root, f.destination);
    completion = Promise.resolve(operation).then(() => { settled = true; }, error => { settled = true; failure = error; });
    await Promise.race([reached, completion.then(() => assert.fail('preparation must wait for its outstanding syncs'))]);
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(settled, false, 'a failed sync must not abandon other admitted syncs');
    assert.equal(fs.existsSync(f.destination), true, 'cleanup waits until no sync still owns a destination fd');
    assert.ok(maximum >= 2 && maximum <= 16, 'the payload sync window must stay bounded');
    held(); await completion;
    assert.match(failure?.message ?? '', /injected_parallel_sync/);
    assert.equal(active, 0); assert.equal(fs.existsSync(f.destination), false);
  } finally {
    closing = true; held?.(); await completion; await Promise.all(callbacks); fs.fsync = original;
  }
});

test('U10 should refuse image preparation when a durable directory sync fails', async t => {
  const f = fixture(t), original = fs.fsync;
  fs.fsync = (fd, callback) => {
    if (fs.fstatSync(fd).isDirectory()) return queueMicrotask(() => callback(Error('injected_directory_sync')));
    return original(fd, callback);
  };
  try { await assert.rejects(() => preparePublishedImage(f.root, f.destination), /injected_directory_sync/); }
  finally { fs.fsync = original; }
  assert.equal(fs.existsSync(f.destination), false); assert.equal(fs.existsSync(f.root), true);
});

import fs from 'node:fs';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
if (!fs.realpathSync('.').startsWith('/tmp/mh-l3-qualification-')) throw Error('private_qualification_copy_required');
const policy = 'packages/h2a/src/runtime/upgrade/image-policy.js', factory = 'scripts/mh-l1-package-prototype.mjs', index = '.git/index';
const preparation = 'packages/h2a/src/runtime/upgrade/published-payload.js';
const published = 'packages/h2a/test/mh-l6-published.test.js', packageTest = 'packages/h2a/test/mh-l6-package.test.js', seamTest = 'packages/h2a/test/succession-lock-seam-guard.test.js';
const cases = [
  ['minimum-libc', policy, [['Number(libc[1]) < 2 || (Number(libc[1]) === 2 && Number(libc[2]) < 31) ||', '']], published, 'U10 should reject a libc below the pinned native baseline before any image preparation'],
  ['unsupported-platform', policy, [[" || process.platform !== 'linux'", '']], published, 'U10 should reject unsupported platform and architecture before creating an image directory'],
  ['unsupported-architecture', policy, [['manifest.profile.arch !== process.arch || ', '']], published, 'U10 should reject unsupported platform and architecture before creating an image directory'],
  ['directory-sync', preparation, [['await syncPaths(levels[depth], true);', 'void levels[depth];']], published, 'U10 should refuse image preparation when a durable directory sync fails'],
  ['outstanding-sync-cleanup', preparation, [['await Promise.allSettled(batch)', 'await Promise.all(batch)']], published, 'U10 should wait for bounded outstanding payload syncs before cleaning a failed image'],
  ['bounded-sync-window', preparation, [['const window = 16;', 'const window = Infinity;']], published, 'U10 should wait for bounded outstanding payload syncs before cleaning a failed image'],
  ['plugin-version', factory, [['plugin.version = releaseVersion; ', '']], packageTest, 'U10 should build the actual closed dependency graph from pinned prebuilds before invoking npm'],
  ['diagnostic-installability', factory, [["    engines: { node: release ?", "    ...(release ? { os: ['linux'], cpu: ['x64'] } : {}),\n    engines: { node: release ?"]], packageTest, 'U10 should install @sentropic/h2a for off-profile diagnostics while refusing H4 preparation'],
  ['distributed-seam', factory, [['  const manifest = createManifest(root, {', "  if (release) cpSync(join(repo, 'packages/h2a/test/succession-lock-test-seam.mjs'), join(root, corePath, 'dist/runtime/local-files/succession-lock-test-seam.mjs'));\n  const manifest = createManifest(root, {"]], seamTest, undefined, 5],
  ['nonempty-source-inventory', index, [], seamTest, undefined, 5],
];
const originals = new Map([...new Set(cases.map(row => row[1]))].map(path => [path, fs.readFileSync(path)]));
const modes = new Map([...originals.keys()].map(path => [path, fs.statSync(path).mode & 0o777]));
const hash = bytes => createHash('sha256').update(bytes).digest('hex'), major = process.versions.node.split('.')[0], results = [];
for (const [name, path, changes, file, scenario, count = 1] of cases) {
  const run = color => {
    const label = `E3b2-${name}-${color}`, result = spawnSync(process.execPath, ['scripts/mh-l6-test.mjs', file, label], {
      env: { ...process.env, ...(scenario ? { MH_L6_CASE: scenario } : {}) }, encoding: 'utf8', maxBuffer: 12 * 1024 * 1024 });
    const log = `docs/plan/mh-l6/evidence/${file.split('/').at(-1)}-node${major}-${label}.log`, text = fs.readFileSync(log, 'utf8'), receipt = JSON.parse(text.split('\nreceipt: ').at(-1));
    if (result.status !== (color === 'red' ? 1 : 0) || receipt.code !== result.status || receipt.invalid || receipt.signal || receipt.tests !== count ||
      (color === 'red' && !text.includes('ERR_ASSERTION'))) throw Error(`invalid_mutation:${name}:${color}:${log}`);
    if (name === 'distributed-seam' && color === 'red' && !text.includes('succession-lock-test-seam.mjs')) throw Error('seam_oracle_not_reached');
    return log;
  };
  let red;
  try {
    if (path === index) fs.unlinkSync(index); // Empty inventory, not a corrupt Git index.
    else {
      let bytes = originals.get(path).toString();
      for (const [from, to] of changes) { if (bytes.split(from).length !== 2) throw Error('mutation_not_unique:' + name); bytes = bytes.replace(from, to); }
      fs.writeFileSync(path, bytes);
    }
    red = run('red');
  } finally { for (const [path, bytes] of originals) { fs.writeFileSync(path, bytes); fs.chmodSync(path, modes.get(path)); } }
  const green = run('green');
  for (const [path, bytes] of originals) if (hash(fs.readFileSync(path)) !== hash(bytes)) throw Error('restore_failed:' + path);
  for (const [path, mode] of modes) if ((fs.statSync(path).mode & 0o777) !== mode) throw Error('mode_restore_failed:' + path);
  results.push({ name, red, green, restored: true });
  fs.writeFileSync(`docs/plan/mh-l6/mutations-package-E3b2-node${major}.json`, JSON.stringify({ node: process.version,
    files: [...originals].map(([path, bytes]) => ({ path, sha256: hash(bytes), mode: modes.get(path), privateFixture: path === index })), results }, null, 2) + '\n');
  console.log(name + ': assertion red, restored green');
}
